import {faultCatalog} from './energy-faults.mjs';
export const dayKey=(date=new Date())=>{const d=new Date(date);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
export function shiftDay(key,n){const d=new Date(key+'T12:00:00');d.setDate(d.getDate()+n);return dayKey(d);}
const intervals=[1,3,7,14,30];
export function createEnergySpacing(storage){const key='mecanica.energy-spacing.v1';let data={goal:2,seen:[],days:{},faults:{}},warning='';try{const s=JSON.parse(storage.getItem(key)||'null');if(s){if(!Number.isInteger(s.goal)||s.goal<1||s.goal>10||!Array.isArray(s.seen)||!s.days||!s.faults)throw Error();data=s;}}catch{warning='No se pudo recuperar el calendario; se reconstruirá con los resultados disponibles.';}
 const save=()=>{try{storage.setItem(key,JSON.stringify(data));}catch{warning='Calendario disponible solo en esta sesión: el navegador no permite guardarlo.';}};
 return {warning:()=>warning,snapshot:()=>structuredClone(data),setGoal(n,today=dayKey()){if(!Number.isInteger(n)||n<1||n>10)return;data.goal=n;data.days[today]??={count:0,goal:n};data.days[today].goal=n;save();},sync(rows){let changed=false;for(const r of [...rows].sort((a,b)=>Date.parse(a.date)-Date.parse(b.date))){if(data.seen.includes(r.id))continue;data.seen.push(r.id);changed=true;const day=dayKey(r.date);data.days[day]??={count:0,goal:data.goal};if(!r.exam||r.score===100)data.days[day].count++;
 for(const f of r.faults){const k=r.lab+':'+f,old=data.faults[k];const clean=r.score>=85&&!r.events.some(e=>e&&Array.isArray(e.targets)&&e.targets.includes(f)&&(e.wrong||e.action==='hint'));let stage=old?.stage??0;if(!clean)stage=0;else if(old&&day>old.last&&day>=old.due)stage=Math.min(4,stage+1);data.faults[k]={stage,last:day,due:shiftDay(day,intervals[stage]),clean};}
 }if(changed)save();},schedule(today=dayKey()){return Object.entries(faultCatalog).flatMap(([lab,fs])=>fs.map(f=>{const s=data.faults[lab+':'+f.id];return {lab,fault:f.id,label:f.label,...s,due:s?.due||today,new:!s,interval:s?intervals[s.stage]:0};})).sort((a,b)=>a.due.localeCompare(b.due));},streak(today=dayKey()){const completed=d=>data.days[d]?.count>=data.days[d]?.goal;let end=completed(today)?today:shiftDay(today,-1),current=0;while(completed(end)){current++;end=shiftDay(end,-1);}let best=0,run=0,prev=null;for(const d of Object.keys(data.days).sort()){run=completed(d)?(prev===shiftDay(d,-1)?run+1:1):0;best=Math.max(best,run);prev=d;}return {current,best};}};
}
